package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.graphics.Typeface;import android.os.*;import android.view.*;import android.widget.*;

/** Shared compact screen for optional library tools. */
abstract class WorkspaceActivity extends Activity {
    LinearLayout content;ScrollView scroll;AppPalette colors;final Handler ui=new Handler(Looper.getMainLooper());
    protected void attachBaseContext(Context c){super.attachBaseContext(AppLanguage.wrap(c));}
    public void onCreate(Bundle state){super.onCreate(state);colors=AppPalette.of(this);LinearLayout root=PlusUi.column(this);root.setFitsSystemWindows(true);root.setBackgroundColor(colors.bg);getWindow().setStatusBarColor(colors.bg);getWindow().setNavigationBarColor(colors.bg);
        if(Build.VERSION.SDK_INT>=35){root.setFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(dp(12)+b.left,dp(6)+b.top,dp(12)+b.right,dp(6)+b.bottom);return insets;});}
        LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);FrameLayout back=new FrameLayout(this);back.addView(new Icons(this,"back",colors.accent),new FrameLayout.LayoutParams(dp(23),dp(23),Gravity.CENTER));android.graphics.drawable.GradientDrawable backShape=new android.graphics.drawable.GradientDrawable();backShape.setColor(colors.tint);backShape.setCornerRadius(dp(14));back.setBackground(backShape);back.setContentDescription(AppLanguage.text(this,"Voltar"));back.setOnClickListener(v->finish());LinearLayout.LayoutParams backParams=new LinearLayout.LayoutParams(dp(44),dp(44));backParams.rightMargin=dp(12);head.addView(back,backParams);TextView title=label(title(),21);title.setTypeface(null,Typeface.BOLD);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(head);
        scroll=new ScrollView(this);content=PlusUi.column(this);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView signature=label("Haidoy Carlos Mautempo",10);signature.setGravity(Gravity.CENTER);root.addView(signature);setContentView(root);UiSpacing.watch(root);load();}
    abstract String title();abstract void load();
    int dp(int n){return PlusUi.dp(this,n);}TextView label(String text,int size){return PlusUi.text(this,text,size);}
    TextView action(String title,Runnable task){TextView b=label(title,14);UiBox.style(b);b.setOnClickListener(v->task.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);content.addView(b,p);return b;}
    void note(String text){TextView t=label(text,13);t.setTextColor(colors.muted);content.addView(t);}
    void row(String icon,String title,String subtitle,Runnable task){LinearLayout card=PlusUi.column(this);card.setPadding(dp(14),dp(13),dp(14),dp(13));android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(colors.surface);shape.setCornerRadius(dp(16));shape.setStroke(dp(1),colors.line);card.setBackground(shape);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(new Icons(this,icon,colors.accent),new LinearLayout.LayoutParams(dp(25),dp(30)));TextView caption=label(title,16);caption.setTypeface(null,Typeface.BOLD);caption.setPadding(dp(12),0,0,0);head.addView(caption,new LinearLayout.LayoutParams(0,-2,1));card.addView(head);if(subtitle!=null&&!subtitle.isEmpty()){TextView sub=label(subtitle,12);sub.setTextColor(colors.muted);sub.setPadding(dp(37),dp(6),0,0);card.addView(sub);}if(task!=null){card.setOnClickListener(v->task.run());card.setFocusable(true);Motion.touch(card);}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);content.addView(card,p);}
    void pager(int page,boolean more,Runnable before,Runnable after){LinearLayout bar=new LinearLayout(this);if(page>0){TextView b=label("Anterior",14);UiBox.style(b);b.setOnClickListener(v->before.run());bar.addView(b,new LinearLayout.LayoutParams(0,-2,1));}if(more){TextView b=label("Seguinte",14);UiBox.style(b);b.setOnClickListener(v->after.run());bar.addView(b,new LinearLayout.LayoutParams(0,-2,1));}content.addView(bar);}
    final Runnable refresh=()->{if(!isFinishing()&&!isDestroyed())load();};final Runnable changed=()->{ui.removeCallbacks(refresh);ui.postDelayed(refresh,200);};
    protected void onStart(){super.onStart();TaskEvents.add(changed);}protected void onStop(){TaskEvents.remove(changed);ui.removeCallbacks(refresh);super.onStop();}
}
